// Every input is public pinned code; venue data is generated by the tests themselves.
import {mkdtempSync,mkdirSync,readFileSync,writeFileSync,cpSync,rmSync,realpathSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join,resolve} from 'node:path';
import {fileURLToPath} from 'node:url';
import {createRequire} from 'node:module';
import {createHash,randomUUID} from 'node:crypto';
import {execFileSync,spawn} from 'node:child_process';
import {setTimeout as delay} from 'node:timers/promises';
import {downloadConformanceArchive} from './conformance-archive.mjs';
import {createInstallObserver} from './conformance-install-observer.mjs';

const replayRevision='fbadd15785464e59747e697c11048bfbc6e4938f';
const browserRevision='99c265981ba98f1afd0e5fc822624a9a91822ad2';
const repository=fileURLToPath(new URL('../..',import.meta.url));
const sha=bytes=>createHash('sha256').update(bytes).digest('hex');
const exports=[
 ['recordSale','packages/core/src/record-sale.ts'],['withTransaction,openVenueDatabase','packages/db/src/index.ts'],
 ['applyMigrations','packages/migrations/src/apply.ts'],['VerifactuBackend','packages/fiscal-verifactu/src/backend.ts'],
 ['registerSif','packages/fiscal-verifactu/src/registro-sif.ts'],['tenants,locations','packages/db/src/schema/tenants.ts'],
 ['nodes','packages/db/src/schema/nodes.ts'],['invoiceSeries','packages/db/src/schema/series.ts'],
 ['sql','packages/db/node_modules/drizzle-orm/index.js'],['ALL_MODULES','packages/composition/src/modules.ts'],
 ['createCloudSnapshotArchive','apps/server/src/cloud-snapshot-archive.ts'],['restoreFromArtifact','apps/server/src/restore.ts'],
 ['businessDayAt,businessDayBounds','packages/shared/src/business-day-clock.ts'],
 ['readLocationClock','packages/reporting/src/business-day.ts'],
 ['Hono','apps/server/node_modules/hono/dist/index.js'],['getRequestListener','apps/server/node_modules/@hono/node-server/dist/index.mjs'],
 ['mountManagementApi','apps/server/src/management-api.ts'],['mountCloudPublic','apps/server/src/cloud-remote.ts'],
 ['provisionVenue,venueModuleConfig','apps/server/src/provision.ts'],['hashPin,hashPassword,registerModulePermissions','packages/identity/src/index.ts'],
 ['ALL_MODULE_PERMISSIONS,ALL_ALERT_CLAIMS,enabledAlertSources','apps/server/src/modules.ts'],
 ['mountMeApi','apps/server/src/me-api.ts'],['mountReportApi','apps/server/src/report-api.ts'],
 ['LiveEvents,mountLiveApi','apps/server/src/live-api.ts'],['liveResourceTypes','apps/server/src/live-resources.ts'],
 ['mountCatalogueApi','apps/server/src/catalogue-api.ts'],['mountAlertsApi','apps/server/src/alerts-api.ts'],
 ['createAlertRegistry','apps/server/src/alerts.ts'],['mountSpa','apps/server/src/spa-api.ts'],
];

const browserExports=[
 ['mountThemesApi','apps/server/src/themes-api.ts'],['mountDiskStopApi','apps/server/src/disk-stop-api.ts'],
];

export async function prepareConformance(selected) {
  const browserFile='remote-browser-conformance.test.mjs';
  if(selected.includes(browserFile)&&selected.length>1) {
    const replay=await prepareConformance(selected.filter(name=>name!==browserFile));
    try {
      const browser=await prepareConformance([browserFile]);
      return {...replay,env:{...replay.env,COST_BROWSER_FIXTURE:browser.env.COST_BROWSER_FIXTURE},
        cleanup:()=>{try {browser.cleanup();} finally {replay.cleanup();}}};
    } catch(error) {replay.cleanup();throw error;}
  }
  // Browser qualification needs stream and unload repairs; replay measurements
  // retain their original source so their fiscal and accounting inputs agree.
  const revision=selected.includes('remote-browser-conformance.test.mjs')?browserRevision:replayRevision;
  const controller=new AbortController();
  const interrupt=()=>controller.abort();
  process.once('SIGINT',interrupt);process.once('SIGTERM',interrupt);
  const root=realpathSync(mkdtempSync(join(tmpdir(),'cloud-cost-conformance-')));
  let ownedImageTag;
  const cleanup=()=>{
    try {if(ownedImageTag) {
      const images=execFileSync('docker',['image','ls','-q',ownedImageTag],{encoding:'utf8',timeout:30000});
      if(images.trim())execFileSync('docker',['image','rm',ownedImageTag],{stdio:'inherit',timeout:30000});
    }} finally {
      rmSync(root,{recursive:true,force:true});
      process.removeListener('SIGINT',interrupt);process.removeListener('SIGTERM',interrupt);
    }
  };
  // Never pass provider, venue or user-specific configuration into the public build.
  const environment={PATH:process.env.PATH,LANG:'C',TZ:'UTC',CI:'true',
    ...(process.env.NODE_AUTH_TOKEN?{NODE_AUTH_TOKEN:process.env.NODE_AUTH_TOKEN}:{})};
  let phase='revision';
  const run=(command,args,{encoding,timeout=300000,captureStderr=false,observeInstall=false,attempt,...options}={})=>{
    controller.signal.throwIfAborted();
    return new Promise((resolve,reject)=>{
      const child=spawn(command,args,{env:environment,stdio:'inherit',...options,detached:true});
      const output=[];let failure,forceTimer,stderr='';
      const started=performance.now(),commandPhase=phase;
      const report=(event,details={})=>console.error('conformance_setup='+JSON.stringify({
        event,phase:commandPhase,command,args,pid:child.pid??null,
        elapsedMs:Math.round(performance.now()-started),timeoutMs:timeout,...(attempt===undefined?{}:{attempt}),...details}));
      report('start');
      const install=observeInstall?createInstallObserver(options.cwd):null;
      const installTimer=install?setInterval(()=>report('install-progress',install.snapshot()),10000):null;
      // This process group belongs to this one setup command and its descendants.
      const stop=signal=>{
        if(!child.pid)return;
        try {process.kill(-child.pid,signal);} catch(error) {if(error.code!=='ESRCH')throw error;}
      };
      const abort=()=>{
        failure=Error('Conformance setup interrupted');report('interrupted');stop('SIGTERM');
        forceTimer=setTimeout(()=>stop('SIGKILL'),1000);
      };
      controller.signal.addEventListener('abort',abort,{once:true});
      child.stdout?.on('data',bytes=>{if(install)install.write(bytes);else output.push(bytes);});
      if(captureStderr)child.stderr?.on('data',bytes=>{
        process.stderr.write(bytes);stderr=(stderr+bytes.toString()).slice(-16384);
      });
      child.on('error',error=>{failure=error;report('spawn-error',{errorCode:error.code});});
      const timer=setTimeout(()=>{failure=Error('Conformance setup timed out');report('timeout');stop('SIGKILL');},timeout);
      child.once('close',(code,signal)=>{
        if(controller.signal.aborted)stop('SIGKILL');
        clearTimeout(timer);clearTimeout(forceTimer);clearInterval(installTimer);controller.signal.removeEventListener('abort',abort);
        if(install){install.end();report('install-progress',install.snapshot());}
        report(failure?'closed':code===0&&!signal?'complete':'failure',{code,signal});
        if(failure||code!==0||signal)reject(Object.assign(failure??Error('Conformance setup command failed: '+command),{stderr}));
        else resolve(encoding?Buffer.concat(output).toString(encoding):Buffer.concat(output));
      });
    });
  };
  const docker=async(...args)=>(await run('docker',args,{encoding:'utf8',stdio:['ignore','pipe','inherit']})).trim();
  const archive=async(url,digest,path)=>{
    await downloadConformanceArchive(url,digest,path,{signal:controller.signal,phase});
    await run('tar',['-xzf',path,'-C',join(path,'..')]);
  };
  const json=(name,value)=>{const path=join(root,name);writeFileSync(path,JSON.stringify(value),{mode:0o600});return path;};
  try {
    const env={COST_CLOUD_REVISION:(await run('git',['rev-parse','HEAD'],{cwd:repository,encoding:'utf8',stdio:'pipe'})).trim()};
    const needsRuntime=selected.some(name=>!/^(fiscal|mail|service-receipt|foreground|remote|worker-storage)-conformance/.test(name));
    let code, stackCode, runtime, migrations;
    if(needsRuntime) {
      const source=join(root,'public-source');
      for(let attempt=1;;attempt++) {
        phase='source-init';
        await run('git',['init','--quiet',source],{attempt});
        phase='source-fetch';
        try {
          await run('git',['-c','http.lowSpeedLimit=1000','-c','http.lowSpeedTime=60',
            '-C',source,'fetch','--quiet','--depth=1','https://github.com/clintongormley/waitron.git',revision],
            {attempt,timeout:75000,captureStderr:true,stdio:['ignore','ignore','pipe']});
          break;
        } catch(error) {
          const terminal=/not our ref|couldn't find remote ref|unadvertised object|invalid refspec|authentication failed|could not read Username|repository .*not found|requested URL returned error: (?:400|401|403|404)/i.test(error.stderr);
          const transport=/operation too slow|timed out|could not resolve host|couldn't resolve host|failed to connect|couldn't connect|connection (?:reset|refused)|TLS|SSL connection|unexpected EOF|early EOF|requested URL returned error: 5\d\d/i.test(error.stderr);
          if(controller.signal.aborted||terminal||attempt>=2||(!transport&&error.message!=='Conformance setup timed out'))throw error;
          // A retry starts from a new owned checkout; no partial Git state survives.
          rmSync(source,{recursive:true,force:true});
        }
      }
      phase='source-checkout';
      await run('git',['-C',source,'checkout','--quiet','--detach','FETCH_HEAD']);
      phase='source-verify';
      if((await run('git',['-C',source,'rev-parse','HEAD'],{encoding:'utf8',stdio:'pipe'})).trim()!==revision) throw Error('Unexpected public source');
      phase='source-install';
      await run('pnpm',['install','--frozen-lockfile','--reporter=ndjson'],{cwd:source,observeInstall:true,stdio:['ignore','pipe','inherit']});
      const {build}=await import(join(source,'node_modules/.pnpm/esbuild@0.28.2/node_modules/esbuild/lib/main.js'));
      code=join(root,'runtime');mkdirSync(code,{mode:0o700});runtime=join(code,'runtime.mjs');
      const entry=join(source,'cloud-cost-entry.mjs');
      writeFileSync(entry,(selected.includes('remote-browser-conformance.test.mjs')?[...exports,...browserExports]:exports).map(([names,path])=>`export {${names}} from ${JSON.stringify('./'+path)};`).join('\n'));
      await build({entryPoints:[entry],outfile:runtime,bundle:true,platform:'node',format:'esm',target:'node26',
        banner:{js:'import {createRequire as cloudCostRequire} from "node:module"; const require=cloudCostRequire(import.meta.url);'},logLevel:'warning'});
      if(selected.includes('remote-browser-conformance.test.mjs')) {
        mkdirSync(join(code,'assets'));
        cpSync(join(source,'apps/server/src/assets/invoice-noto-sans.ttf'),join(code,'assets/invoice-noto-sans.ttf'));
        const tokens=join(code,'node_modules/@waitron/ui-core');
        mkdirSync(join(tokens,'src/tokens'),{recursive:true});
        cpSync(join(source,'packages/ui-core/package.json'),join(tokens,'package.json'));
        for(const name of ['colors.css','structure.css'])
          cpSync(join(source,'packages/ui-core/src/tokens',name),join(tokens,'src/tokens',name));
      }
      writeFileSync(join(code,'runtime-manifest.json'),JSON.stringify({schemaVersion:1,revision,sha256:sha(readFileSync(runtime))}));
      const sets=JSON.parse(readFileSync(join(source,'packages/migrations/migrations.manifest.json')));
      mkdirSync(join(code,'packages/migrations'),{recursive:true});
      cpSync(join(source,'packages/migrations/migrations.manifest.json'),join(code,'packages/migrations/migrations.manifest.json'));
      migrations=join(root,'migrations');mkdirSync(migrations);
      for(const set of sets) {
        const from=resolve(source,'packages/migrations',set.from);
        cpSync(from,resolve(code,'packages/migrations',set.from),{recursive:true});
        cpSync(from,join(migrations,set.name),{recursive:true});
      }
      writeFileSync(join(migrations,'manifest.json'),JSON.stringify(sets));
      if(selected.includes('stack-conformance.test.mjs')) {
        stackCode=join(root,'stack-runtime');cpSync(code,stackCode,{recursive:true});
        const stackEntry=join(source,'cloud-cost-stack-entry.mjs');
        writeFileSync(stackEntry,exports.filter(([names])=>names!=='businessDayAt,businessDayBounds')
          .map(([names,path])=>`export {${names}} from ${JSON.stringify('./'+path)};`).join('\n'));
        const stackRuntime=join(stackCode,'runtime.mjs');
        await build({entryPoints:[stackEntry],outfile:stackRuntime,bundle:true,platform:'node',format:'esm',target:'node26',
          banner:{js:'import {createRequire as cloudCostRequire} from "node:module"; const require=cloudCostRequire(import.meta.url);'},logLevel:'warning'});
        writeFileSync(join(stackCode,'runtime-manifest.json'),JSON.stringify({schemaVersion:1,revision,sha256:sha(readFileSync(stackRuntime))}));
      }

      const stateParent=join(root,'state');mkdirSync(stateParent,{mode:0o700});
      env.COST_SYNTHETIC_CONFIG=json('synthetic.json',{codeRoot:code,stateParent});
      env.COST_OWNER_FIXTURE=json('owner.json',{revision,runtime,runtimeSha256:sha(readFileSync(runtime)),migrations});
      if(selected.includes('remote-browser-conformance.test.mjs')) {
        phase='dashboard-build';
        await run('pnpm',['--dir','apps/dashboard','build'],{cwd:source});
        env.COST_BROWSER_FIXTURE=json('browser.json',{revision,runtime,runtimeSha256:sha(readFileSync(runtime)),migrations,runtimeAssets:join(code,'assets'),runtimePackages:join(code,'node_modules'),assets:join(source,'apps/dashboard/dist')});
      }
    }
    const imageNeeded=selected.some(name=>/^(stack|isolated-replay|paced-replay|worker-storage)-/.test(name));
    let image;
    if(imageNeeded) {
      const context=join(root,'image');mkdirSync(context);
      phase='image-architecture';
      const architecture=await docker('info','--format','{{.Architecture}}');
      const platform=/^(aarch64|arm64)$/.test(architecture)?'linux-arm64':/^(x86_64|amd64)$/.test(architecture)?'linux-x64':null;
      if(!platform)throw Error('Unsupported Docker architecture');
      const streamPin=platform==='linux-arm64'
        ?['litestream-0.5.17-linux-arm64.tar.gz','f8ca4a050095c1efbda2c4365172e61bf9d955ea0d9ac42f448b52e51819baa5']
        :['litestream-0.5.17-linux-x86_64.tar.gz','cfb371176d164437ae869f8351cfde49bd1804ae71c61923f75c9cba9c9c006d'];
      phase='litestream-archive';
      await archive('https://github.com/benbjohnson/litestream/releases/download/v0.5.17/'+streamPin[0],streamPin[1],join(context,streamPin[0]));
      const litestreamBinary=join(context,'litestream');
      const pin=platform==='linux-arm64'?['linux_arm64.tar.gz','ba5c9def9ff98f78becdf309a50a9f906922f6383a7c4c772d01ede3cc012e16']:
        ['linux_amd64.tar.gz','31fb804858885f9e7f18b6d3b1da09e824baac3e6a55b5a62c3c4c77e6ed6d7d'];
      phase='storage-archive';
      await archive('https://github.com/seaweedfs/seaweedfs/releases/download/4.47/'+pin[0],pin[1],join(context,'weed.tar.gz'));
      // Bundle the repository's locked SDK, without fetching credentials or a provider endpoint.
      const {build}=createRequire(new URL('../../packages/ui-smoke/package.json',import.meta.url))('esbuild');
      mkdirSync(join(context,'sdk/node_modules/@aws-sdk/client-s3'),{recursive:true});
      writeFileSync(join(context,'sdk/package.json'),'{}');
      await build({stdin:{contents:"module.exports=require('@aws-sdk/client-s3')",resolveDir:join(repository,'packages/backups')},
        outfile:join(context,'sdk/node_modules/@aws-sdk/client-s3/index.js'),bundle:true,platform:'node',format:'cjs',target:'node26'});
      cpSync(new URL('./fixtures/conformance.Dockerfile',import.meta.url),join(context,'Dockerfile'));
      writeFileSync(join(context,'.dockerignore'),'*\n!Dockerfile\n!weed\n!sdk/\n!sdk/**\n');
      const tag='waitron-cloud-cost-conformance:'+randomUUID();
      ownedImageTag=tag;
      phase='fixture-image-build';
      // Every build attempt and pause shares the original five-minute build budget.
      const deadline=performance.now()+300000;
      const remaining=()=>Math.ceil(deadline-performance.now());
      for(let attempt=1;;attempt++) {
        if(remaining()<=0)throw Error('Conformance fixture image build timed out');
        try {
          await run('docker',['build','--build-arg','FIXTURE_UID='+process.getuid(),'--build-arg','FIXTURE_GID='+process.getgid(),'-t',tag,context],
            {attempt,timeout:remaining(),captureStderr:true,stdio:['ignore','inherit','pipe']});
          break;
        } catch(error) {
          const pause=attempt*1000;
          const terminal=/denied|unauthorized|authentication required|manifest unknown|not found|toomanyrequests|rate limit|invalid reference format/i.test(error.stderr);
          const transient=/failed to resolve source metadata[^\n]*unexpected status from (?:HEAD|GET) request to https:\/\/registry-1\.docker\.io\/v2\/[^\s"]+: 5\d\d\b/i.test(error.stderr);
          if(controller.signal.aborted||terminal||!transient||attempt>=3||remaining()<=pause)throw error;
          console.error('Conformance registry metadata unavailable; retrying fixture image ('+(attempt+1)+'/3)');
          try {await delay(pause,undefined,{signal:controller.signal});} catch(interruption) {
            if(controller.signal.aborted)throw Error('Conformance setup interrupted',{cause:interruption});
            throw interruption;
          }
        }
      }
      phase='fixture-image-inspect';
      image=await docker('image','inspect',tag,'--format','{{.Id}}');
      env.COST_STACK_FIXTURE=json('stack.json',{codeCache:stackCode??code,image,litestreamBinary});
    }
    const ensureImage=async name=>{
      phase='image-acquisition';
      // Cache inspection, all pull attempts and backoff share the existing five-minute budget.
      const deadline=performance.now()+300000;
      const remaining=()=>Math.ceil(deadline-performance.now());
      const command=async args=>{
        if(remaining()<=0)throw Error('Conformance image acquisition timed out');
        await run('docker',args,{timeout:remaining(),captureStderr:true,stdio:['ignore',args[0]==='pull'?'inherit':'ignore','pipe']});
      };
      try {await command(['image','inspect',name]);return;} catch(error) {
        if(controller.signal.aborted||!/No such (?:image|object):/i.test(error.stderr))throw error;
      }
      for(let attempt=1;;attempt++) {
        try {await command(['pull',name]);return;} catch(error) {
          const pause=attempt*1000;
          const terminal=/denied|unauthorized|authentication required|manifest unknown|not found|toomanyrequests|rate limit/i.test(error.stderr);
          const transient=/Client\.Timeout|i\/o timeout|TLS handshake timeout|context deadline exceeded|connection reset by peer|unexpected EOF/i.test(error.stderr);
          if(controller.signal.aborted||terminal||!transient||attempt>=3||remaining()<=pause)throw error;
          console.error('Conformance image pull lost its connection; retrying '+name+' ('+(attempt+1)+'/3)');
          try {await delay(pause,undefined,{signal:controller.signal});} catch(interruption) {
            if(controller.signal.aborted)throw Error('Conformance setup interrupted',{cause:interruption});
            throw interruption;
          }
        }
      }
    };
    if(selected.some(name=>/^(foreground|isolated-replay|paced-replay|stack|remote)/.test(name)))await ensureImage('node:26.11.1-slim');
    if(selected.some(name=>/^remote/.test(name))) {
      phase='gateway-image';
      try {await docker('image','inspect','waitron-cloud-local-remote:dev');} catch {
        await run('docker',['build','-f','deploy/local-remote/Dockerfile','-t','waitron-cloud-local-remote:dev','.'],{cwd:repository});
      }
    }
    if(selected.includes('remote-browser-conformance.test.mjs'))await ensureImage('mcr.microsoft.com/playwright:v1.63.0-noble');
    controller.signal.throwIfAborted();
    return {env,image,cleanup};
  } catch(error) {cleanup();throw error;}
}
